1	#!/usr/bin/env node
2	// Gate 03 — runtime. Serves dist/ with a fresh nonce per response and the strict CSP + Trusted Types
3	// policy below. Part of the harness (verify.sh gate 0 checks it is untouched).
4	import http from 'node:http';
5	import fs from 'node:fs';
6	import path from 'node:path';
7	import crypto from 'node:crypto';
8	
9	const args = process.argv.slice(2);
10	const arg = (name, fallback) => {
11	  const i = args.indexOf(name);
12	  return i >= 0 ? args[i + 1] : fallback;
13	};
14	const PORT = Number(arg('--port', process.env.PORT ?? 4174));
15	const HOST = '127.0.0.1';
16	const DIST = path.resolve(import.meta.dirname, '..', 'dist');
17	const REPORT_LOG = process.env.CSP_REPORT_LOG ?? path.resolve(import.meta.dirname, '..', '..', 'runs', 'arm-b-csp-reports.jsonl');
18	
19	/** The policies a string may come out of. Everything else is refused by the browser. */
20	export const TRUSTED_TYPES_POLICIES = ['default', 'google#safe', 'dompurify'];
21	
22	export function buildCsp(nonce) {
23	  return [
24	    `script-src 'nonce-${nonce}' 'strict-dynamic'`,
25	    `object-src 'none'`,
26	    `base-uri 'none'`,
27	    `require-trusted-types-for 'script'`,
28	    `trusted-types ${TRUSTED_TYPES_POLICIES.join(' ')}`,
29	    `report-uri /csp-report`,
30	  ].join('; ');
31	}
32	
33	const SECURITY_HEADERS = {
34	  'X-Content-Type-Options': 'nosniff',
35	  'X-Frame-Options': 'DENY',
36	  'Cross-Origin-Opener-Policy': 'same-origin',
37	  'Cross-Origin-Resource-Policy': 'same-origin',
38	  'Referrer-Policy': 'no-referrer',
39	};
40	
41	const MIME = {
42	  '.html': 'text/html; charset=utf-8',
43	  '.js': 'text/javascript; charset=utf-8',
44	  '.mjs': 'text/javascript; charset=utf-8',
45	  '.css': 'text/css; charset=utf-8',
46	  '.json': 'application/json; charset=utf-8',
47	  '.svg': 'image/svg+xml',
48	  '.png': 'image/png',
49	  '.ico': 'image/x-icon',
50	  '.woff2': 'font/woff2',
51	  '.txt': 'text/plain; charset=utf-8',
52	};
53	
54	function logReport(kind, body, req) {
55	  let parsed = body;
56	  try {
57	    parsed = JSON.parse(body);
58	  } catch {
59	    /* keep raw */
60	  }
61	  const line = { ts: new Date().toISOString(), kind, report: parsed, ua: req.headers['user-agent'] ?? '' };
62	  try {
63	    fs.mkdirSync(path.dirname(REPORT_LOG), { recursive: true });
64	    fs.appendFileSync(REPORT_LOG, JSON.stringify(line) + '\n');
65	  } catch {
66	    /* logging is best-effort */
67	  }
68	  const summary =
69	    kind === 'csp-report'
70	      ? `${parsed?.['csp-report']?.['violated-directive'] ?? '?'} blocked ${parsed?.['csp-report']?.['blocked-uri'] ?? ''} ${parsed?.['csp-report']?.['script-sample'] ?? ''}`
71	      : `${parsed?.sink ?? '?'} ${JSON.stringify(parsed?.sample ?? '').slice(0, 120)}`;
72	  console.error(`[${kind}] ${summary}`);
73	}
74	
75	const server = http.createServer((req, res) => {
76	  const url = new URL(req.url ?? '/', `http://${HOST}:${PORT}`);
77	
78	  if (req.method === 'POST' && (url.pathname === '/csp-report' || url.pathname === '/tt-report')) {
79	    let body = '';
80	    req.on('data', (chunk) => {
81	      if (body.length < 65536) body += chunk;
82	    });
83	    req.on('end', () => {
84	      logReport(url.pathname.slice(1), body, req);
85	      res.writeHead(204).end();
86	    });
87	    return;
88	  }
89	  if (req.method !== 'GET' && req.method !== 'HEAD') {
90	    res.writeHead(405, { Allow: 'GET, HEAD' }).end();
91	    return;
92	  }
93	
94	  let pathname = decodeURIComponent(url.pathname);
95	  if (pathname.endsWith('/')) pathname += 'index.html';
96	  const file = path.normalize(path.join(DIST, pathname));
97	  if (!file.startsWith(DIST + path.sep)) {
98	    res.writeHead(403).end();
99	    return;
100	  }
101	  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) {
102	    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8', ...SECURITY_HEADERS }).end('not found');
103	    return;
104	  }
105	
106	  const ext = path.extname(file);
107	  if (ext === '.html') {
108	    const nonce = crypto.randomBytes(16).toString('base64');
109	    const html = fs
110	      .readFileSync(file, 'utf8')
111	      .replace(/<script\b(?![^>]*\bnonce=)/g, `<script nonce="${nonce}"`);
112	    res.writeHead(200, {
113	      'Content-Type': MIME['.html'],
114	      'Content-Security-Policy': buildCsp(nonce),
115	      'Cache-Control': 'no-store',
116	      ...SECURITY_HEADERS,
117	    });
118	    res.end(req.method === 'HEAD' ? undefined : html);
119	    return;
120	  }
121	  res.writeHead(200, { 'Content-Type': MIME[ext] ?? 'application/octet-stream', 'Cache-Control': 'no-cache', ...SECURITY_HEADERS });
122	  if (req.method === 'HEAD') res.end();
123	  else fs.createReadStream(file).pipe(res);
124	});
125	
126	if (!fs.existsSync(path.join(DIST, 'index.html'))) {
127	  console.error(`harness/server.mjs: ${DIST}/index.html not found — run "pnpm build" first`);
128	  process.exit(1);
129	}
130	server.listen(PORT, HOST, () => {
131	  console.error(`arm B (harness) serving ${DIST} at http://${HOST}:${PORT}/ — strict CSP + Trusted Types enforced; reports → ${REPORT_LOG}`);
132	});
133

