:root {
  --ink: #16211f;
  --ink-soft: #4a5b58;
  --line: #d8e0de;
  --surface: #ffffff;
  --page: #f4f6f5;
  --accent: #0f766e;
  --accent-soft: #e6f2f0;
  --focus: #b45309;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 2rem 1rem 4rem;
  background: var(--page);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  display: grid;
  gap: 1.75rem;
  margin: 0 auto;
  max-width: 46rem;
}

h1 {
  margin: 0 0 0.25rem;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

h2 {
  margin: 0 0 1rem;
  font-size: 1.15rem;
}

.tagline {
  margin: 0;
  color: var(--ink-soft);
}

#note-form,
.board {
  padding: 1.25rem;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.field {
  display: grid;
  gap: 0.35rem;
  margin-bottom: 1rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--ink-soft);
}

input,
textarea {
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  color: inherit;
  font: inherit;
  width: 100%;
}

textarea {
  resize: vertical;
}

.hint {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

button.primary {
  padding: 0.55rem 1.1rem;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

button.primary:hover {
  background: #0b5d57;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

#results-line {
  margin: 0 0 1rem;
  color: var(--ink-soft);
  font-size: 0.9rem;
  min-height: 1.35rem;
}

#feed {
  display: grid;
  gap: 0.85rem;
}

.note {
  padding: 0.9rem 1rem;
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 10px;
  background: var(--surface);
}

.note[aria-current="true"] {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.note-avatar {
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--accent-soft);
}

.note-heading {
  margin: 0;
  font-size: 1.05rem;
}

button.note-title {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

button.note-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-date {
  display: block;
  margin-top: 0.6rem;
  color: var(--ink-soft);
  font-size: 0.78rem;
}

.feed-empty {
  margin: 0;
  color: var(--ink-soft);
}

@media (prefers-color-scheme: dark) {
  :root {
    --ink: #e8efed;
    --ink-soft: #a3b3b0;
    --line: #2c3a38;
    --surface: #131b1a;
    --page: #0b1211;
    --accent: #5eead4;
    --accent-soft: #17302d;
    --focus: #fbbf24;
    color-scheme: dark;
  }

  button.primary {
    color: #06201d;
  }

  button.primary:hover {
    background: #86f0e0;
  }
}

