// Temporary manual smoke check (deleted after running). Drives the built app on the harness server.
import { chromium } from '@playwright/test';

const BASE = 'http://127.0.0.1:4179/';
const results = [];
const check = (name, ok, detail = '') => results.push({ name, ok, detail });

const browser = await chromium.launch();
const page = await browser.newPage();
const dialogs = [];
const errors = [];
page.on('dialog', (d) => {
  dialogs.push(d.message());
  d.dismiss();
});
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => {
  if (m.type() === 'error') errors.push(m.text());
});

await page.goto(BASE);

// --- seed + ordering ---
const ids = await page.locator('article.note').evaluateAll((els) => els.map((e) => e.dataset.noteId));
check('seeded 6 fixtures newest-first', JSON.stringify(ids) === JSON.stringify(['6', '5', '4', '3', '2', '1']), ids.join(','));

// --- rich text ---
check('bold renders as <b>', (await page.locator('[data-note-id="1"] .note-body b').innerText()) === 'OWASP AppSec Days Porto');
check('italic renders as <i>', (await page.locator('[data-note-id="2"] .note-body i').innerText()) === 'Ribeira');
check('<br> renders', (await page.locator('[data-note-id="1"] .note-body br').count()) === 1);
const link = page.locator('[data-note-id="4"] .note-body a');
check('link is clickable', (await link.getAttribute('href')) === 'https://www.livrarialello.pt/', await link.getAttribute('href'));
check('avatar rendered when given', (await page.locator('[data-note-id="1"] img.note-avatar').count()) === 1);
check('no avatar when blank', (await page.locator('[data-note-id="2"] img.note-avatar').count()) === 0);

// --- search + results line ---
await page.fill('#search', 'douro');
const shown = await page.locator('article.note').evaluateAll((els) => els.map((e) => e.dataset.noteId));
check('search filters (case-insensitive, title or body)', JSON.stringify(shown) === JSON.stringify(['5', '2']), shown.join(','));
check('results line', (await page.locator('#results-line').innerText()) === 'results for "douro"', await page.locator('#results-line').innerText());
check('fragment has q', page.url().endsWith('#q=douro'), page.url());

// --- selection + deep link ---
await page.locator('[data-note-id="5"] .note-title').click();
check('fragment q+note', page.url().endsWith('#q=douro&note=5'), page.url());
check('aria-current on selected note', (await page.locator('[data-note-id="5"]').getAttribute('aria-current')) === 'true');
check('exactly one aria-current', (await page.locator('[aria-current="true"]').count()) === 1);

// --- restore on reload ---
await page.reload();
check('query restored', (await page.inputValue('#search')) === 'douro');
check('selection restored', (await page.locator('[data-note-id="5"]').getAttribute('aria-current')) === 'true');
check('results line restored', (await page.locator('#results-line').innerText()) === 'results for "douro"');

// --- deep link entered directly ---
await page.goto(`${BASE}#q=port&note=3`);
