// Temporary manual smoke check (deleted after running). Drives the built app on the harness server.
import { chromium } from '@playwright/test';

const BASE = 'http://127.0.0.1:4179/';
const results = [];
const check = (name, ok, detail = '') => results.push({ name, ok, detail });

const browser = await chromium.launch();
const page = await browser.newPage();
const dialogs = [];
const errors = [];
page.on('dialog', (d) => {
  dialogs.push(d.message());
  d.dismiss();
});
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => {
  if (m.type() === 'error') errors.push(m.text());
});

await page.goto(BASE);

// --- seed + ordering ---
const ids = await page.locator('article.note').evaluateAll((els) => els.map((e) => e.dataset.noteId));
check('seeded 6 fixtures newest-first', JSON.stringify(ids) === JSON.stringify(['6', '5', '4', '3', '2', '1']), ids.join(','));

// --- rich text ---
check('bold renders as <b>', (await page.locator('[data-note-id="1"] .note-body b').innerText()) === 'OWASP AppSec Days Porto');
check('italic renders as <i>', (await page.locator('[data-note-id="2"] .note-body i').innerText()) === 'Ribeira');
check('<br> renders', (await page.locator('[data-note-id="1"] .note-body br').count()) === 1);
const link = page.locator('[data-note-id="4"] .note-body a');
check('link is clickable', (await link.getAttribute('href')) === 'https://www.livrarialello.pt/', await link.getAttribute('href'));
check('avatar rendered when given', (await page.locator('[data-note-id="1"] img.note-avatar').count()) === 1);
check('no avatar when blank', (await page.locator('[data-note-id="2"] img.note-avatar').count()) === 0);

// --- search + results line ---
await page.fill('#search', 'douro');
const shown = await page.locator('article.note').evaluateAll((els) => els.map((e) => e.dataset.noteId));
check('search filters (case-insensitive, title or body)', JSON.stringify(shown) === JSON.stringify(['5', '2']), shown.join(','));
check('results line', (await page.locator('#results-line').innerText()) === 'results for "douro"', await page.locator('#results-line').innerText());
check('fragment has q', page.url().endsWith('#q=douro'), page.url());

// --- selection + deep link ---
await page.locator('[data-note-id="5"] .note-title').click();
check('fragment q+note', page.url().endsWith('#q=douro&note=5'), page.url());
check('aria-current on selected note', (await page.locator('[data-note-id="5"]').getAttribute('aria-current')) === 'true');
check('exactly one aria-current', (await page.locator('[aria-current="true"]').count()) === 1);

// --- restore on reload ---
await page.reload();
check('query restored', (await page.inputValue('#search')) === 'douro');
check('selection restored', (await page.locator('[data-note-id="5"]').getAttribute('aria-current')) === 'true');
check('results line restored', (await page.locator('#results-line').innerText()) === 'results for "douro"');

// --- deep link entered directly ---
await page.goto(`${BASE}#q=port&note=3`);
check('direct deep link: query', (await page.inputValue('#search')) === 'port');
check('direct deep link: fragment kept', page.url().endsWith('#q=port&note=3'), page.url());
// Note 3 does not match "port", so the filter hides it; the selection is still held.
check('filter wins over selection', (await page.locator('[data-note-id="3"]').count()) === 0);

// --- clearing the query empties the results line and reveals the still-selected note ---
await page.fill('#search', '');
check('empty query clears results line', (await page.locator('#results-line').innerText()) === '');
check('fragment keeps note only', page.url().endsWith('#note=3'), page.url());
check('selection survived filtering', (await page.locator('[data-note-id="3"]').getAttribute('aria-current')) === 'true');

// --- add a note ---
await page.fill('#title', 'Cais da Ribeira');
await page.fill('#body', 'Meet at <b>19:00</b>.\nBring a <i>jacket</i> and see <a href="https://example.com/x">the plan</a>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
const first = page.locator('article.note').first();
check('new note is first', (await first.getAttribute('data-note-id')) === '7', await first.getAttribute('data-note-id'));
check('new note bold', (await first.locator('.note-body b').innerText()) === '19:00');
check('newline became <br>', (await first.locator('.note-body br').count()) === 1);
check('new note link', (await first.locator('.note-body a').getAttribute('href')) === 'https://example.com/x');
check('new note avatar', (await first.locator('img.note-avatar').getAttribute('src')) === 'https://example.com/a.png');
check('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');

await page.reload();
check('new note persisted', (await page.locator('[data-note-id="7"]').count()) === 1);
await page.fill('#search', 'jacket');
check('search matches rendered body text', (await page.locator('article.note').count()) === 1);
await page.fill('#search', '');

// --- empty submit is a no-op ---
const before = await page.locator('article.note').count();
await page.click('#note-form button[type=submit]');
check('empty submit adds nothing', (await page.locator('article.note').count()) === before);

// --- payloads stay inert ---
const payloads = [
  '<img src=x onerror=alert(1)>',
  '<script>alert(1)</script>',
  '<a href="javascript:alert(1)">click</a>',
  '<a href="JaVaScRiPt&#58;alert(1)">click</a>',
  '<svg/onload=alert(1)>',
  '<iframe srcdoc="<script>alert(1)</script>"></iframe>',
  '<b onmouseover="alert(1)">hover</b>',
  '<a href=" javascript:alert(1)">spaced</a>',
  '<details open ontoggle=alert(1)>',
  '"><script>alert(1)</script>',
  '<b>bold</b><script>alert(1)</script>',
];
for (const [i, payload] of payloads.entries()) {
  await page.fill('#title', `payload ${i}`);
  await page.fill('#body', payload);
  await page.fill('#avatar', payload);
  await page.click('#note-form button[type=submit]');
}
await page.waitForTimeout(300);
const note = page.locator('article.note').first();
await note.locator('.note-body').hover().catch(() => {});
const html = await page.locator('#feed').innerHTML();
check('no dialogs fired', dialogs.length === 0, dialogs.join(' | '));
check('no script elements in feed', (await page.locator('#feed script').count()) === 0);
check('no img/svg/iframe injected', (await page.locator('#feed img:not(.note-avatar), #feed svg, #feed iframe').count()) === 0);
check('no handler attributes in feed html', !/on(error|load|toggle|mouseover)\s*=/i.test(html));
check('no javascript: URL in feed html', !/javascript:/i.test(html));
check('bold survives alongside a payload', (await page.locator('article.note').first().locator('.note-body b').innerText()) === 'bold');
check('avatar payloads rejected', (await page.locator('#feed img.note-avatar[src*="onerror"]').count()) === 0);
check('no page errors', errors.length === 0, errors.join(' | '));

await browser.close();

let failed = 0;
for (const r of results) {
  if (!r.ok) failed++;
  console.log(`${r.ok ? 'ok  ' : 'FAIL'}  ${r.name}${r.detail && !r.ok ? `  -> ${r.detail}` : ''}`);
}
console.log(`\n${results.length - failed}/${results.length} passed`);
process.exit(failed === 0 ? 0 : 1);

