  '<a href="javascript:alert(1)">click</a>',
  '<a href="JaVaScRiPt&#58;alert(1)">click</a>',
  '<svg/onload=alert(1)>',
  '<iframe srcdoc="<script>alert(1)</script>"></iframe>',
  '<b onmouseover="alert(1)">hover</b>',
  '<a href=" javascript:alert(1)">spaced</a>',
  '<details open ontoggle=alert(1)>',
  '"><script>alert(1)</script>',
  '<b>bold</b><script>alert(1)</script>',
];
for (const [i, payload] of payloads.entries()) {
  await page.fill('#title', `payload ${i}`);
  await page.fill('#body', payload);
  await page.fill('#avatar', payload);
  await page.click('#note-form button[type=submit]');
}
await page.waitForTimeout(300);
const note = page.locator('article.note').first();
await note.locator('.note-body').hover().catch(() => {});
const html = await page.locator('#feed').innerHTML();
check('no dialogs fired', dialogs.length === 0, dialogs.join(' | '));
check('no script elements in feed', (await page.locator('#feed script').count()) === 0);
check('no img/svg/iframe injected', (await page.locator('#feed img:not(.note-avatar), #feed svg, #feed iframe').count()) === 0);
check('no handler attributes in feed html', !/on(error|load|toggle|mouseover)\s*=/i.test(html));
check('no javascript: URL in feed html', !/javascript:/i.test(html));
check('bold survives alongside a payload', (await page.locator('article.note').first().locator('.note-body b').innerText()) === 'bold');
check('avatar payloads rejected outright', (await page.locator('#feed img.note-avatar').count()) === 2, `${await page.locator('#feed img.note-avatar').count()} avatars (2 fixtures expected)`);
check('no page errors', errors.length === 0, errors.join(' | '));

await browser.close();

let failed = 0;
for (const r of results) {
  if (!r.ok) failed++;
  console.log(`${r.ok ? 'ok  ' : 'FAIL'}  ${r.name}${r.detail && !r.ok ? `  -> ${r.detail}` : ''}`);
}
console.log(`\n${results.length - failed}/${results.length} passed`);
process.exit(failed === 0 ? 0 : 1);

